   776→        function parseConversation(filename, content) {
   777→            const lines = content.trim().split('\n');
   778→            const messages = [];
   779→            let summary = '';
   780→            let sessionId = '';
   781→            let gitBranch = '';
   782→            let agentId = '';
   783→            let isAgent = filename.includes('agent-');
   784→
   785→            lines.forEach(line => {
   786→                try {
   787→                    const obj = JSON.parse(line);
   788→                    if (obj.type === 'summary') {
   789→                        summary = obj.summary;
   790→                    } else if (obj.type === 'user' || obj.type === 'assistant') {
   791→                        if (!sessionId && obj.sessionId) sessionId = obj.sessionId;
   792→                        if (!gitBranch && obj.gitBranch) gitBranch = obj.gitBranch;
   793→                        if (!agentId && obj.agentId) agentId = obj.agentId;
   794→
   795→                        // Skip internal "Warmup" messages in agent sessions
   796→                        if (isAgent && obj.type === 'user' && obj.message?.content === 'Warmup') {
   797→                            return;
   798→                        }
   799→                        messages.push(obj);
   800→                    } else if (obj.type === 'system') {
   801→                        messages.push(obj);
   802→                    }
   803→                } catch (e) {}
   804→            });
   805→
   806→            const id = filename.split('/').pop().replace('.jsonl', '');
   807→            currentConversation = id;
   808→            conversations[id] = { filename, summary, sessionId, gitBranch, agentId, isAgent, messages };
   809→        }
