   823→        function renderMessages() {
   824→            const conv = conversations[currentConversation];
   825→            if (!conv) return;
   826→
   827→            const showUser = document.getElementById('showUser').checked;
   828→            const showAssistant = document.getElementById('showAssistant').checked;
   829→            const showTools = document.getElementById('showTools').checked;
   830→            const showSystem = document.getElementById('showSystem').checked;
   831→
   832→            const filtered = conv.messages.filter(m => {
   833→                // Tool results come as type: "user" but should be filtered with Tools
   834→                const isToolResult = m.type === 'user' &&
   835→                    Array.isArray(m.message?.content) &&
   836→                    m.message.content.some(c => c.type === 'tool_result');
   837→
   838→                if (isToolResult) return showTools;
   839→                if (m.type === 'user') return showUser;
   840→                if (m.type === 'assistant') return showAssistant;
   841→                if (m.type === 'system') return showSystem;
   842→                return true;
   843→            });
   844→
   845→            messagesContainer.innerHTML = filtered.map(msg => renderMessage(msg, showTools)).join('');
   846→        }
   847→
   848→        function renderMessage(msg, showTools) {
   849→            const time = msg.timestamp ? new Date(msg.timestamp).toLocaleTimeString(undefined, {hour: '2-digit', minute: '2-digit'}) : '';
   850→
   851→            // Check if this is a tool_result message (comes as type: "user" but is really tool output)
   852→            const isToolResult = msg.type === 'user' &&
   853→                Array.isArray(msg.message?.content) &&
   854→                msg.message.content.some(c => c.type === 'tool_result');
   855→
   856→            const role = isToolResult ? 'tool' : (msg.type === 'user' ? 'user' : (msg.type === 'assistant' ? 'assistant' : 'system'));
   857→
   858→            let content = '';
   859→
   860→            // Handle system messages (different structure)
   861→            if (msg.type === 'system') {
   862→                const parts = [];
   863→                if (msg.subtype) parts.push(`[${msg.subtype}]`);
   864→                if (msg.hookInfos && msg.hookInfos.length > 0) {
   865→                    parts.push(`Hooks: ${msg.hookInfos.map(h => h.command).join(', ')}`);
   866→                }
   867→                if (msg.stopReason) parts.push(`Stop: ${msg.stopReason}`);
   868→                if (msg.level) parts.push(`Level: ${msg.level}`);
   869→                content = escapeHtml(parts.join(' | ') || 'System event');
   870→            } else if (msg.message) {
   871→                if (typeof msg.message.content === 'string') {
   872→                    content = escapeHtml(msg.message.content);
   873→                } else if (Array.isArray(msg.message.content)) {
   874→                    content = msg.message.content.map(c => {
   875→                        if (c.type === 'text') {
   876→                            return escapeHtml(c.text);
   877→                        } else if (c.type === 'image' && c.source) {
   878→                            // Handle base64 images
   879→                            const src = c.source.type === 'base64'
   880→                                ? `data:${c.source.media_type};base64,${c.source.data}`
   881→                                : c.source.url;
   882→                            return `<div class="image-container"><img class="message-image" src="${src}" alt="Image"></div>`;
   883→                        } else if (c.type === 'tool_use' && showTools) {
   884→                            return renderToolUse(c);
   885→                        } else if (c.type === 'tool_result' && showTools) {
   886→                            return renderToolResult(c);
   887→                        }
   888→                        return '';
   889→                    }).join('');
   890→                }
   891→            }
   892→
   893→            if (!content.trim()) return '';
   894→
   895→            // Build tooltip data with ALL non-id attributes
   896→            const tooltipData = {};
   897→            if (msg.message?.model) tooltipData.model = msg.message.model;
   898→            if (msg.agentId) tooltipData.agent = msg.agentId;
   899→            if (msg.gitBranch) tooltipData.branch = msg.gitBranch;
   900→            if (msg.version) tooltipData.version = msg.version;
   901→            if (msg.isSidechain !== undefined) tooltipData.sidechain = msg.isSidechain;
   902→            if (msg.cwd) tooltipData.cwd = msg.cwd;
   903→            if (msg.userType) tooltipData.userType = msg.userType;
   904→            if (msg.message?.stop_reason) tooltipData.stop_reason = msg.message.stop_reason;
   905→            if (msg.message?.usage) {
   906→                const u = msg.message.usage;
   907→                tooltipData.tokens = `in:${u.input_tokens || 0} out:${u.output_tokens || 0}`;
   908→                if (u.cache_read_input_tokens) tooltipData.cache_read = u.cache_read_input_tokens;
   909→                if (u.cache_creation_input_tokens) tooltipData.cache_create = u.cache_creation_input_tokens;
   910→            }
   911→            if (msg.parentUuid) tooltipData.parent = msg.parentUuid;
   912→            if (msg.requestId) tooltipData.request = msg.requestId;
   913→
   914→            const uuid = msg.uuid || '';
   915→            const selectedClass = currentMessage === uuid ? ' selected' : '';
   916→
   917→            // Check if content is only tool calls (no text)
   918→            let isToolsOnly = false;
   919→            if (Array.isArray(msg.message?.content)) {
   920→                const hasText = msg.message.content.some(c => c.type === 'text' && c.text?.trim());
   921→                const hasTools = msg.message.content.some(c => c.type === 'tool_use' || c.type === 'tool_result');
   922→                isToolsOnly = hasTools && !hasText;
   923→            }
   924→            const toolsOnlyClass = isToolsOnly ? ' tools-only' : '';
   925→
   926→            return `
   927→                <div class="message ${role}${selectedClass}" data-tooltip='${JSON.stringify(tooltipData)}' data-uuid="${uuid}">
   928→                    <div class="message-header">
   929→                        <span class="message-role ${role}">${role}</span>
   930→                        <span class="message-time">${time}</span>
   931→                    </div>
   932→                    <div class="message-content${toolsOnlyClass}">${content}</div>
   933→                </div>
   934→            `;
   935→        }
