function renderSessionsList(sessions) {
    // Separate main sessions from agent sessions
    const mainSessions = sessions.filter(s => !s.agentId);
    const agentSessions = sessions.filter(s => s.agentId);

    // Build a map of parent session ID -> agent sessions
    const agentsByParent = {};
    agentSessions.forEach(s => {
        const parentId = s.parentSessionId;
        if (!agentsByParent[parentId]) {
            agentsByParent[parentId] = [];
        }
        agentsByParent[parentId].push(s);
    });

    // Count main sessions (agents are nested, not counted separately)
    const mainCount = mainSessions.length;
    const agentCount = agentSessions.length;

    let html = `
        <div class="back-btn" onclick="goBackToProjects()">Back</div>
        <div class="list-header">Sessions (${mainCount} main, ${agentCount} agents)</div>
    `;

    if (sessions.length === 0) {
        html += '<div class="empty-state"><p>No sessions</p></div>';
    } else {
        // Render main sessions with their nested agents
        mainSessions.forEach(s => {
            const d = new Date(s.modified * 1000);
            const dateStr = d.toLocaleDateString(undefined, {month: 'short', day: 'numeric'});
            const timeStr = d.toLocaleTimeString(undefined, {hour: '2-digit', minute: '2-digit'});
            const displayName = s.summary || s.name.replace('.jsonl', '').slice(0, 20);

            // Check if this session has agents
            const sessionId = s.name.replace('.jsonl', '');
            const childAgents = agentsByParent[sessionId] || [];
            const hasAgents = childAgents.length > 0;
            const agentBadge = hasAgents ? `<span class="agent-badge">${childAgents.length} agents</span>` : '';
            const hasAgentsClass = hasAgents ? ' has-agents' : '';

            html += `
                <div class="session-item${hasAgentsClass}" onclick="loadConversation('${s.path}')">
                    <div class="session-name">${displayName}${agentBadge}</div>
                    <div class="session-meta">${dateStr}, ${timeStr}</div>
                </div>
            `;

            // Render nested agent sessions
            childAgents.forEach(agent => {
                const ad = new Date(agent.modified * 1000);
                const aDateStr = ad.toLocaleDateString(undefined, {month: 'short', day: 'numeric'});
                const aTimeStr = ad.toLocaleTimeString(undefined, {hour: '2-digit', minute: '2-digit'});
                const agentDisplayName = agent.summary || `agent-${agent.agentId}`;

                html += `
                    <div class="session-item agent-session" onclick="loadConversation('${agent.path}')">
                        <div class="session-name">${agentDisplayName}</div>
                        <div class="session-meta">${aDateStr}, ${aTimeStr}</div>
                    </div>
                `;
            });
        });
    }

    listContainer.innerHTML = html;
}

