// Cache for loaded agent conversations
let loadedAgentConversations = {};

async function loadConversation(filePath, pushState = true) {
    messagesContainer.innerHTML = '<div class="loading">Loading...</div>';
    try {
        let content;
        // Try direct file fetch first (static mode), fall back to API
        if (indexData) {
            const response = await fetch(filePath);
            content = await response.text();
        } else {
            const response = await fetch(`/api/conversation?file=${encodeURIComponent(filePath)}`);
            content = await response.text();
        }
        parseConversation(filePath, content);

        // Load related agent sessions
        const sessionId = filePath.split('/').pop().replace('.jsonl', '');
        const relatedAgents = agentsByParentSession[sessionId] || [];
        loadedAgentConversations = {};

        for (const agent of relatedAgents) {
            try {
                let agentContent;
                if (indexData) {
                    const resp = await fetch(agent.path);
                    agentContent = await resp.text();
                } else {
                    const resp = await fetch(`/api/conversation?file=${encodeURIComponent(agent.path)}`);
                    agentContent = await resp.text();
                }
                loadedAgentConversations[agent.agentId] = parseAgentConversation(agent.path, agentContent);
            } catch (e) {
                console.error('Failed to load agent:', agent.agentId, e);
            }
        }

        renderConversation();
        if (pushState) updateUrl();
    } catch (e) {
        messagesContainer.innerHTML = '<div class="empty-state"><p>Failed to load</p></div>';
    }
}

function parseAgentConversation(filename, content) {
    const lines = content.trim().split('\n');
    const messages = [];
    let summary = '';
    let agentId = '';

    lines.forEach(line => {
        try {
            const obj = JSON.parse(line);
            if (obj.type === 'summary') {
                summary = obj.summary;
            } else if (obj.type === 'user' || obj.type === 'assistant') {
                if (!agentId && obj.agentId) agentId = obj.agentId;
                // Skip "Warmup" messages
                if (obj.type === 'user' && obj.message?.content === 'Warmup') {
                    return;
                }
                messages.push(obj);
            }
        } catch (e) {}
    });

    return { filename, summary, agentId, messages };
}

