// Find all tool headers and check for Task
const toolHeaders = document.querySelectorAll('.tool-header');
const taskTools = [];
toolHeaders.forEach(h => {
    if (h.textContent === 'Task') {
        taskTools.push(h.parentElement.outerHTML.substring(0, 200));
    }
});
JSON.stringify({count: taskTools.length, samples: taskTools.slice(0, 2)});

// Wait a moment for content to load, then search
setTimeout(() => {}, 500);
const toolHeaders = document.querySelectorAll('.tool-header');
const taskTools = [];
toolHeaders.forEach(h => {
    if (h.textContent === 'Task') {
        taskTools.push(h.closest('.tool-use')?.outerHTML?.substring(0, 300) || 'found');
    }
});
JSON.stringify({count: taskTools.length});

// Find and scroll to Task tool
const toolHeaders = document.querySelectorAll('.tool-header');
for (const h of toolHeaders) {
    if (h.textContent === 'Task') {
        h.scrollIntoView({behavior: 'instant', block: 'center'});
        break;
    }
}
'scrolled';

