function renderAgentInline(agentId, agentConv) {
    const title = agentConv.summary || `Agent ${agentId}`;
    const msgCount = agentConv.messages.length;

    const messagesHtml = agentConv.messages.map(msg => {
        const time = msg.timestamp ? new Date(msg.timestamp).toLocaleTimeString(undefined, {hour: '2-digit', minute: '2-digit'}) : '';
        const role = msg.type === 'user' ? 'user' : 'assistant';

        let content = '';
        if (msg.message) {
            if (typeof msg.message.content === 'string') {
                content = escapeHtml(msg.message.content);
            } else if (Array.isArray(msg.message.content)) {
                content = msg.message.content.map(c => {
                    if (c.type === 'text') return escapeHtml(c.text);
                    if (c.type === 'tool_use') return `<div class="tool-use"><div class="tool-header">${escapeHtml(c.name)}</div></div>`;
                    return '';
                }).join('');
            }
        }

        if (!content.trim()) return '';

        return `
            <div class="message ${role}">
                <div class="message-header">
                    <span class="message-role ${role}">${role}</span>
                    <span class="message-time">${time}</span>
                </div>
                <div class="message-content">${content}</div>
            </div>
        `;
    }).join('');

    return `
        <div class="agent-inline-section">
            <div class="agent-inline-header" onclick="toggleAgentContent('${agentId}')">
                <span class="agent-icon">⚡</span>
                <span class="agent-title">${escapeHtml(title)}</span>
                <span class="agent-toggle">${msgCount} messages ▼</span>
            </div>
            <div class="agent-inline-content" id="agent-content-${agentId}">
                ${messagesHtml}
            </div>
        </div>
    `;
}

function toggleAgentContent(agentId) {
    const content = document.getElementById('agent-content-' + agentId);
    if (content) {
        content.classList.toggle('expanded');
    }
}

