function renderMessages() {
    const conv = conversations[currentConversation];
    if (!conv) return;

    const showUser = document.getElementById('showUser').checked;
    const showAssistant = document.getElementById('showAssistant').checked;
    const showTools = document.getElementById('showTools').checked;
    const showSystem = document.getElementById('showSystem').checked;

    const filtered = conv.messages.filter(m => {
        // Tool results come as type: "user" but should be filtered with Tools
        const isToolResult = m.type === 'user' &&
            Array.isArray(m.message?.content) &&
            m.message.content.some(c => c.type === 'tool_result');

        if (isToolResult) return showTools;
        if (m.type === 'user') return showUser;
        if (m.type === 'assistant') return showAssistant;
        if (m.type === 'system') return showSystem;
        return true;
    });

    // Render messages - agents are inserted inline after Task tool results
    messagesContainer.innerHTML = filtered.map(msg => renderMessage(msg, showTools)).join('');
